struct Tick { double px; long long qty; };

template <class Derived>
struct Handler {
    inline void process(const Tick& t) noexcept {
        // ... common pre-work (timestamp, validation) ...
        static_cast<Derived*>(this)->onTick(t);   // static, inlinable dispatch
        // ... common post-work (metrics) ...
    }
};

struct MyStrategy : Handler<MyStrategy> {
    double position = 0;
    inline void onTick(const Tick& t) noexcept {
        // type-specific hot-path logic, no virtual call
        if (t.px < fair_) position += t.qty;
    }
    double fair_ = 100.0;
};

// Usage: MyStrategy s; s.process(tick);  // onTick resolved & inlined at compile time

// Before: virtual dispatch (indirection, no inlining)
struct Strategy { virtual void onTick(const Tick&) = 0; virtual ~Strategy()=default; };

// After: template the runner on the concrete type -> direct, inlinable calls
template <class S>
void run(S& strat, const Tick* ticks, int n) {
    for (int i = 0; i < n; ++i)
        strat.onTick(ticks[i]);     // resolved at compile time, inlined
}

// Or CRTP if you want a shared base with static dispatch:
template <class D> struct StrategyBase {
    void handle(const Tick& t) { static_cast<D*>(this)->onTick(t); } // inlinable
};
struct MyStrategy : StrategyBase<MyStrategy> {
    void onTick(const Tick& t) noexcept { /* hot logic, no vtable */ }
};
